import React from 'react';
import styled from 'styled-components';

const Links = React.forwardRef((props, ref) => {
    return (
        <MainBox>
            <Title>Pobierz wzory niezbędnych dokumentów</Title>
            <Row>
                <div>
                    <TitleBox>
                        <h2 style={{ 'textAlign': 'center' }}>Wzory umów w działalności gospodarczej</h2>
                    </TitleBox>
                    <Document>Umowa kupna sprzedazy</Document>
                </div>
            </Row>
        </MainBox>
    );
});

export default Links

const MainBox = styled.div`
    padding: 48px;
    background-color: #f8f8f8;
`;

const Row = styled.div`
    display: flex;
    flex-direction: row;
`;

const TitleBox = styled.div`
    height: auto;
    width: 40%;
    display: flex;
    align-self: baseline;
    align-items: center;
    justify-content: center;
    background-color: #fff;
    border: 5px solid #D5992E;
    border-radius: 25px;
    box-shadow: -20px 20px #D5992E;
    margin-bottom: 20px;
    margin-left: 20px;
    padding: 24px;
`;

const Title = styled.h1`
    text-align: center;
`;

const Document = styled.a`
    font-family: 'Source Sans Pro', sans-serif;
`;
